<?php
require_once __DIR__ . '/config/config.php';
$user = require_auth();
if (hasRole('EMPLOYEE') && !hasAnyRole(['ADMIN', 'HR', 'MANAGER'])) {
    redirect('employee/dashboard.php');
}
if (!hasAnyRole(['ADMIN', 'HR', 'MANAGER'])) {
    http_response_code(403);
    exit('You are not authorized to access this page.');
}
$pageTitle = 'Dashboard';
$pdo = db();
$metrics = [];
foreach ([['Total Employees','SELECT COUNT(*) FROM employees'],['Active Employees',"SELECT COUNT(*) FROM employees WHERE employment_status = 'Active'"],['Probationary Employees',"SELECT COUNT(*) FROM employees WHERE employment_status = 'Probationary'"],['Departments','SELECT COUNT(*) FROM departments WHERE is_active = 1'],['Positions','SELECT COUNT(*) FROM positions WHERE is_active = 1'],['Branches','SELECT COUNT(*) FROM branches WHERE is_active = 1']] as [$label, $query]) $metrics[$label] = (int) $pdo->query($query)->fetchColumn();
$recentEmployees = $pdo->query('SELECT e.employee_number, e.first_name, e.last_name, e.employment_status, e.created_at, d.name AS department_name, p.name AS position_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN positions p ON p.id=e.position_id ORDER BY e.created_at DESC LIMIT 6')->fetchAll();
$activities = $pdo->query('SELECT a.action, a.entity_type, a.created_at, u.username FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 6')->fetchAll();
require __DIR__ . '/includes/header.php';
?><div class="flex flex-col md:flex-row md:items-end md:justify-between gap-4 mb-8"><div><p class="text-sm text-slate-500">Good day, <?= e(explode(' ', (string) (current_user()['employee_name'] ?: current_user()['username']))[0]) ?>.</p><h1 class="font-display text-3xl font-bold mt-1">People overview</h1></div><?php if (hasAnyRole(['ADMIN', 'HR'])): ?><a href="<?= url('admin/employees/create.php') ?>" class="rounded-lg bg-teal-700 px-5 py-3 text-sm font-bold text-white hover:bg-teal-800">+ Add employee</a><?php endif; ?></div><div class="grid grid-cols-2 xl:grid-cols-6 gap-4 mb-8"><?php foreach ($metrics as $label => $value): ?><div class="metric-card bg-white rounded-xl border border-slate-200 p-5"><p class="text-xs uppercase tracking-wide text-slate-500 font-bold"><?= e($label) ?></p><p class="font-display text-3xl font-bold mt-3"><?= e($value) ?></p></div><?php endforeach; ?></div><div class="grid xl:grid-cols-[1.6fr_1fr] gap-6"><section class="bg-white border border-slate-200 rounded-xl"><div class="p-6 border-b border-slate-100 flex justify-between items-center"><div><h2 class="font-display text-xl font-bold">Recent employees</h2><p class="text-sm text-slate-500 mt-1">Latest records added to Core HR</p></div><a class="text-sm font-bold text-teal-700" href="<?= url('admin/employees.php') ?>">View all</a></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-xs uppercase text-slate-400 bg-slate-50"><tr><th class="px-6 py-3">Employee</th><th class="px-6 py-3">Department</th><th class="px-6 py-3">Status</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($recentEmployees as $employee): ?><tr><td class="px-6 py-4"><p class="font-bold"><?= e($employee['first_name'] . ' ' . $employee['last_name']) ?></p><p class="text-xs text-slate-400"><?= e($employee['employee_number']) ?> · <?= e($employee['position_name'] ?? 'Unassigned') ?></p></td><td class="px-6 py-4 text-slate-600"><?= e($employee['department_name'] ?? 'Unassigned') ?></td><td class="px-6 py-4"><span class="rounded-full px-3 py-1 text-xs font-bold <?= $employee['employment_status'] === 'Active' ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700' ?>"><?= e($employee['employment_status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section><section class="bg-white border border-slate-200 rounded-xl"><div class="p-6 border-b border-slate-100"><h2 class="font-display text-xl font-bold">Recent HR activity</h2><p class="text-sm text-slate-500 mt-1">Account and record events</p></div><div class="p-6 space-y-5"><?php if (!$activities): ?><p class="text-sm text-slate-500">Activity will appear here as the team works.</p><?php endif; ?><?php foreach ($activities as $activity): ?><div class="flex gap-3"><span class="w-2 h-2 mt-2 rounded-full bg-teal-600 shrink-0"></span><div><p class="text-sm font-semibold"><?= e($activity['action']) ?> <span class="font-normal text-slate-500"><?= e($activity['entity_type']) ?></span></p><p class="text-xs text-slate-400 mt-1"><?= e($activity['username'] ?? 'System') ?> · <?= e(date('M j, Y g:i A', strtotime($activity['created_at']))) ?></p></div></div><?php endforeach; ?></div></section></div><?php require __DIR__ . '/includes/footer.php';